// apps/web/src/modules/16-bereavement — the M16 read/write access layer the §5 screens share
// (Track B / ADR-0030, ADR-0032).
//
// Every wire shape below is a TYPE ALIAS into the generated `operations` map
// (packages/ui/src/core/api/schema.ts, regenerated by `bun run client:gen` from
// scripts/openapi/enrichments.ts's M16 request/response TypeBox schemas) — never a hand-copied
// interface. That is what lets every `client.GET`/`POST`/`PATCH` call below go through WITHOUT an
// `as never`/`as unknown as` cast (TASK-022): the parameter and return types are literally the
// server contract, so a route/DTO drift is a compile error here instead of a silent runtime
// mismatch discovered in a screen fifteen files away.
//
// Two server contracts every write helper honours (§F08 / §2.5): a mutating route requires an
// `Idempotency-Key`, and a state transition requires `If-Match` carrying the row `version` the caller READ
// (a 412 means the row moved under you — reload, never retry blind). The server stays the only
// authorization point: nothing here decides what a caller may see.
//
// THE OPTIONAL-VS-NULL RULE the DTOs below preserve. `currentRiskTier?: string | null` is a three-valued
// field on purpose: ABSENT means "the D10 volunteer scope or the §7.13 Part 2 gate withheld it", `null`
// means "no tier has been computed yet", and a value is a value. Collapsing absent into null in the web
// layer would tell a volunteer that a high-risk survivor is unscored.
import type { ApiClient, operations } from "@chartwarden/ui";

// ── schema-derived type extraction (TASK-022) ──────────────────────────────────────────────────────────

/** The `application/json` payload of an openapi-fetch response/request-body slot. */
type Json<T> = T extends { content: { "application/json": infer B } } ? B : never;
/** The 200 response body of operation `Op`. */
type Ok<Op> = Op extends { responses: { 200: infer R } } ? Json<R> : never;
/** The request body of operation `Op` (works whether `requestBody` is required or optional). */
type ReqBody<Op> = Op extends { requestBody?: infer RB } ? Json<RB> : never;
/** The query-parameter object of operation `Op`. */
type ReqQuery<Op> = Op extends { parameters: { query?: infer Q } } ? Q : never;

// ── wire shapes (schema-derived) ───────────────────────────────────────────────────────────────────────

/** §4.6.1 — the paginated envelope M16 pins (`{data, next_cursor, has_more}`, NOT `{items, nextCursor}`). */
export interface CursorPage<T> {
  data: T[];
  next_cursor: string | null;
  has_more: boolean;
  total_count?: number;
}

type PlanListPage = Ok<operations["getApiV1BereavementPlans"]>;
/** Route 1 — one row of the plan worklist. */
export type PlanListItem = PlanListPage["data"][number];

/** One survivor as the plan detail / roster renders them. Sourced off the PATCH-contact response, which is
 *  the only route that returns a bare `ContactRow` at the top level rather than nested under a plan. */
export type ContactRow = Ok<operations["patchApiV1BereavementContactsByContactId"]>;

/** Route 2 — the plan header with its rolled-up roster + risk. */
export type PlanDetail = Ok<operations["getApiV1BereavementPlansByPlanId"]>;

/** The §2.6 outreach rollup both dashboards and the closure record carry (COUNTS, never a rate). */
export type OutreachStats = PlanDetail["stats"];

/**
 * D16 — the external-source provenance an HL7 ADT plan carries.
 *
 * NOTE (TASK-022 drift): the generated shape does NOT match the old hand-written interface field-for-field.
 * It is `sourceProposalId` / `sourceMessageId` / `sourceFacilityMdmId` / `sourceFacilityName` /
 * `ackReceivedAt` / `cosignStatus` / `cosignedAt?` / `medicalDirectorMembershipId?` — there is no
 * `sourceFacility`, `sourceSystem`, `ackAt`, or `cosignedByUserId`, and no index signature. Any screen
 * reading the old field names will now fail to compile; see the final report.
 */
export type ExternalSourceMetadata = NonNullable<PlanDetail["externalSource"]>;

/** Route 10 — the §3.3.7 closure record (§7.15 survey reconstruction). */
export type ClosureView = Ok<operations["getApiV1BereavementPlansByPlanIdClosure"]>;

/** Route 19 — one scheduled or historical touchpoint. Sourced off the start-outreach response, the only
 *  route that returns a bare `OutreachRow` at the top level. */
export type OutreachRow = Ok<operations["postApiV1BereavementOutreachByOutreachIdStart"]>;

/** Route 29 — one immutable row of the append-only score ledger. */
export type RiskScoreRow = Ok<operations["postApiV1BereavementPlansByPlanIdRecomputerisk"]>;

/** Route 30 — the counselor's own caseload plus what is coming due. */
export type CounselorDashboard = Ok<operations["getApiV1BereavementDashboardCounselor"]>;

/** Route 31 — the full-tenant rollups (COUNTS, never rates — CMS small-N suppression lives downstream). */
export type SupervisorDashboard = Ok<operations["getApiV1BereavementDashboardSupervisor"]>;

/** Route 5's answer: the opened plan plus what opening it produced. */
export type PlanActivation = Ok<
  operations["postApiV1BereavementPlansByPlanIdSeedrosterandschedule"]
>;

/** Route 27's answer: what the regeneration actually materialized (never a bare 204). */
export type ScheduleRegeneration = Ok<
  operations["postApiV1BereavementPlansByPlanIdRegenerateschedule"]
>;

/** Routes 21/26/32's answer: the `bereavement_contact_log` row the transition wrote. */
export type ContactLogRow = Ok<operations["postApiV1BereavementContactsByContactIdLogdirect"]>;

/** One roster addition (§4.2 `AdditionalContactBody`, shared by routes 5 and 11). */
export type ContactDraft = ReqBody<operations["postApiV1BereavementPlansByPlanIdContacts"]>;

